const missions=[
{name:'First contact',th:'เริ่มออกสำรวจ',start:[0,4,1],goal:[4,4],gems:[[2,4]],walls:[[1,2],[2,2],[3,2],[4,2]],energy:12,target:4,tip:'เดินหน้า 4 ครั้ง ลูกศรบนหุ่นยนต์บอกทิศที่หันอยู่'},
{name:'Around the corner',th:'เลี้ยวให้ถูกทาง',start:[0,5,0],goal:[4,2],gems:[[0,2],[4,2]],walls:[[1,3],[2,3],[3,3],[4,3]],energy:18,target:8,tip:'เดินขึ้นไปเก็บคริสตัลก่อน แล้วหมุนขวาเพื่อไปถึงฐาน'},
{name:'Loop station',th:'พลังของ Repeat',start:[0,5,0],goal:[5,0],gems:[[0,2],[3,0]],walls:[[1,1],[1,2],[1,3],[2,3],[3,3],[4,3]],energy:16,target:7,tip:'Repeat เดิน 3 ครั้ง ทำให้โปรแกรมสั้นลง ลองใช้ทั้งขาขึ้นและขาไปขวา'},
{name:'Sensor alley',th:'ตรวจจับกำแพง',start:[0,5,1],goal:[4,1],gems:[[3,5],[3,1]],walls:[[4,5],[4,4],[4,3],[4,2],[2,4],[2,3],[2,2]],energy:18,target:8,tip:'IF ด้านหน้าตัน → หมุนซ้าย มิฉะนั้นเดินหน้า ใช้ตอนถึงมุมกำแพง'},
{name:'Crystal shuffle',th:'ภารกิจสุ่มคริสตัล',start:[0,5,0],goal:[5,0],gems:[],walls:[[1,1],[1,2],[1,3],[2,3],[3,3],[4,3]],energy:15,target:7,tip:'คริสตัลสุ่มบนขอบซ้ายและขอบบนทุกครั้งที่เข้าด่าน ต้องเก็บครบด้วยพลังงาน 15 หน่วย'}];
const labels={F:'↑ เดินหน้า',L:'↶ หมุนซ้าย',R:'↷ หมุนขวา',T:'⟳ Repeat เดิน 3 ครั้ง',I:'◇ IF ตัน:ซ้าย / ไม่ตัน:เดิน'};
const $=id=>document.getElementById(id),dirs=[[0,-1],[1,0],[0,1],[-1,0]];let level=0,player='Hero',program=[],robot,remaining,energy,running=false,token=0,attempts=0,active=-1,scores={};try{scores=JSON.parse(localStorage.getItem('robot-mission-v1')||'{}')||{}}catch{}
function wall(x,y){return x<0||y<0||x>5||y>5||missions[level].walls.some(p=>p[0]===x&&p[1]===y)}
function status(t,good=false){$('status').textContent=t;$('status').style.color=good?'#d5fa74':''}
function drawLevels(){$('levels').innerHTML='';missions.forEach((m,i)=>{const b=document.createElement('button');b.className='level'+(i===level?' active':'');b.innerHTML=`${scores[player+'-'+i]?'★'.repeat(scores[player+'-'+i]):'0'+(i+1)} &nbsp; ${m.th}<small>${m.name.toUpperCase()}</small>`;b.onclick=()=>load(i);$('levels').append(b)});$('progress').textContent=missions.filter((_,i)=>scores[player+'-'+i]).length+' / 5 MISSIONS COMPLETE'}
function render(){const m=missions[level];$('grid').innerHTML='';for(let y=0;y<6;y++)for(let x=0;x<6;x++){const el=document.createElement('div');el.className='cell'+(wall(x,y)?' wall':'')+(m.goal[0]===x&&m.goal[1]===y?' goal':'');el.setAttribute('aria-label',`${x},${y}`);if(m.goal[0]===x&&m.goal[1]===y)el.textContent='◎';if(remaining.some(p=>p[0]===x&&p[1]===y)){el.textContent='◆';el.style.color='#bca7ff'}if(robot[0]===x&&robot[1]===y){el.textContent='';const r=document.createElement('div');r.className='bot';r.textContent='▲';r.style.transform=`rotate(${robot[2]*90}deg)`;el.append(r)}$('grid').append(el)}$('direction').textContent=['N / เหนือ','E / ตะวันออก','S / ใต้','W / ตะวันตก'][robot[2]];$('energy').textContent=energy;$('gems').textContent=`${m.gems.length-remaining.length}/${m.gems.length}`;$('count').textContent=`${program.length}/20`;$('queue').innerHTML='';if(!program.length)$('queue').innerHTML='<div class="empty">＋ เลือกคำสั่งด้านบน<br>แล้วเรียงแผนการเดินทางที่นี่</div>';program.forEach((cmd,i)=>{const row=document.createElement('div');row.className='cmd'+(active===i?' running':'');row.innerHTML=`<small>${i+1}</small><span>${labels[cmd]}</span>`;[['↑',()=>move(i,-1)],['↓',()=>move(i,1)],['×',()=>{program.splice(i,1);render()}]].forEach(([s,f])=>{const b=document.createElement('button');b.textContent=s;b.disabled=running;b.onclick=f;row.append(b)});$('queue').append(row)});document.querySelectorAll('#palette button').forEach(b=>b.disabled=running||program.length>=20);$('run').disabled=running||!program.length;$('clear').disabled=running;drawLevels()}
function reset(){token++;running=false;active=-1;robot=[...missions[level].start];remaining=missions[level].gems.map(p=>[...p]);energy=missions[level].energy;$('next').classList.add('hidden');render();status(`${player} พร้อมแล้ว • เก็บคริสตัลให้ครบ แล้วไปที่ ◎ ลองได้ไม่จำกัดครั้ง`)}
function load(i){level=i;program=[];attempts=0;if(i===4){missions[i].gems=[[0,4],[0,3],[0,2],[0,1],[0,0],[1,0],[2,0],[3,0],[4,0]].map(p=>({p,k:Math.random()})).sort((a,b)=>a.k-b.k).slice(0,3).map(v=>v.p)}$('title').textContent=`0${i+1} / ${missions[i].name}`;$('target').textContent=`เป้า ≤ ${missions[i].target} บล็อก`;$('tip').textContent='💡 '+missions[i].tip;$('palette').innerHTML='';Object.keys(labels).filter(k=>k!=='T'&&k!=='I'||k==='T'&&i>=2||k==='I'&&i>=3).forEach(k=>{const b=document.createElement('button');b.textContent=labels[k];b.onclick=()=>{if(!running&&program.length<20){program.push(k);render()}};$('palette').append(b)});reset()}
function move(i,d){if(running||i+d<0||i+d>=program.length)return;[program[i],program[i+d]]=[program[i+d],program[i]];render()}
function act(cmd){if(energy<=0)return 'พลังงานหมด ลองลดจำนวนการเคลื่อนที่ดู';energy--;if(cmd==='L')robot[2]=(robot[2]+3)%4;else if(cmd==='R')robot[2]=(robot[2]+1)%4;else{const [dx,dy]=dirs[robot[2]],x=robot[0]+dx,y=robot[1]+dy;if(wall(x,y))return 'ชนกำแพงแล้ว! ลองตรวจทิศ แล้วเพิ่มคำสั่งเลี้ยว';robot[0]=x;robot[1]=y;remaining=remaining.filter(p=>p[0]!==x||p[1]!==y)}return null}
async function run(){reset();running=true;attempts++;const ticket=token;render();let error=null;outer:for(let i=0;i<program.length;i++){active=i;const cmd=program[i];for(let n=0;n<(cmd==='T'?3:1);n++){if(ticket!==token)return;let primitive=cmd;if(cmd==='T')primitive='F';if(cmd==='I'){const [dx,dy]=dirs[robot[2]];primitive=wall(robot[0]+dx,robot[1]+dy)?'L':'F'}error=act(primitive);render();status(`กำลังทำงาน • คำสั่ง ${i+1}/${program.length} • ${labels[cmd]}`);await new Promise(r=>setTimeout(r,Number($('speed').value)));if(ticket!==token)return;if(error)break outer}}running=false;active=-1;const m=missions[level];if(error)status(error);else if(robot[0]===m.goal[0]&&robot[1]===m.goal[1]&&!remaining.length){const stars=program.length<=m.target?(attempts===1?3:2):1;scores[player+'-'+level]=Math.max(scores[player+'-'+level]||0,stars);try{localStorage.setItem('robot-mission-v1',JSON.stringify(scores))}catch{}status(`${'★'.repeat(stars)} สำเร็จ ${player}! ใช้ ${program.length} บล็อก • สลับคนวางแผนกับคนเขียนโค้ดได้เลย`,true);$('next').textContent=level===4?'↺ กลับไปภารกิจแรก':'ภารกิจถัดไป →';$('next').classList.remove('hidden')}else status(remaining.length?`ยังเหลือคริสตัล ${remaining.length} ชิ้น ปรับคำสั่งแล้ว Run ใหม่ได้เลย`:'เก็บครบแล้ว! เพิ่มคำสั่งให้ไปถึงฐาน ◎');render()}
$('run').onclick=run;$('reset').onclick=reset;$('clear').onclick=()=>{program=[];reset()};$('next').onclick=()=>load((level+1)%5);['Hero','Shokun'].forEach(p=>$(p.toLowerCase()).onclick=()=>{player=p;$('hero').classList.toggle('active',p==='Hero');$('shokun').classList.toggle('active',p==='Shokun');load(level)});load(0);
